// It returns an error if the edge is not defined in the schema.
func (m *UsuarioMutation) ResetEdge(name string) error {
	switch name {
	case usuario.EdgeRefreshTokens:
		m.ResetRefreshTokens()
		return nil
	case usuario.EdgePasswordResetTokens:
		m.ResetPasswordResetTokens()
		return nil
	case usuario.EdgeAssignedContacts:
		m.ResetAssignedContacts()
		return nil
	}
	return fmt.Errorf("unknown Usuario edge %s", name)
}
